-- seed-state-legislators batch 04
-- States: NM, NY, NC, ND, OH, OK, OR, PA, RI, SC
-- Paste into Supabase SQL Editor AFTER migration-selection-method-and-legislative.sql
-- Safe to re-run for these states.

delete from public.state_officials
where court_or_agency = 'Legislative Branch'
  and state_code in ('NM', 'NY', 'NC', 'ND', 'OH', 'OK', 'OR', 'PA', 'RI', 'SC');

insert into public.state_officials (
  full_name,
  title,
  court_or_agency,
  level,
  state_code,
  district_number,
  county_name,
  party,
  photo_url,
  selection_method,
  appointed_by
)
